-- ════════════════════════════════════════════════════════════════════════════
--  132 · Rastreio — situação do pedido no painel da fulfillment, vista por fora da API (pedido do Lucas, 16/11/2026)
--
--  A API da Jetpack (JetStream) diz "received"/"processing", mas não diz POR QUE o pedido não sai. A auditoria do painel FulFil (16/11, Claude no
--  navegador, doc "Auditoria do painel Jetpack (FulFil) vs SendTrace") mostrou que 43 dos 49 atrasados nem chegaram à Jetpack (presos no middleware,
--  quase todos por SKU inválido), 4 estão em hold por endereço e 2 foram cancelados lá como teste. Esta tabela guarda essa explicação por pedido;
--  a aba Rastreio mostra o selo na lista e o texto na ficha, e o Atlas lê a mesma tabela. Só aparece enquanto o pedido está pendente.
--    situacao = nao_entrou | hold_endereco | cancelado_teste
--  Aditiva e idempotente (ON CONFLICT DO NOTHING). Desfazer: DROP TABLE public.rastreio_situacao_fulfillment;
-- ════════════════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS public.rastreio_situacao_fulfillment (
  transacao_id  text        PRIMARY KEY,
  provedor      text        NOT NULL,
  pedido        text,
  situacao      text        NOT NULL CHECK (situacao IN ('nao_entrou', 'hold_endereco', 'cancelado_teste')),
  detalhe       text        NOT NULL,
  sku           text,
  fonte         text        NOT NULL DEFAULT 'Auditoria do painel Jetpack (FulFil) em 16/11/2026',
  visto_em      timestamptz NOT NULL DEFAULT '2026-11-16 15:45:00+00',
  criado_em     timestamptz NOT NULL DEFAULT now()
);

ON CONFLICT (transacao_id) DO NOTHING;

-- o Atlas lê esta tabela pela chave de leitura
DO $$ BEGIN
  IF to_regprocedure('public.atualizar_grants_leitura()') IS NOT NULL THEN PERFORM public.atualizar_grants_leitura(); END IF;
END $$;
